INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `description`, `created_at`, `updated_at`) VALUES (18, 'donation_instructions', 'Welcome to the official FreynixRO Support & Donation Portal!\n\nAll contributions go directly toward sustaining our high-performance dedicated server hosting, automated daily off-site backups, DDoS mitigation, anti-cheat licensing, and ongoing episode content expansions.\n\n⚡ Instant Automated Delivery:\nDonations completed via PayPal are automatically processed via IPN within seconds. Your Cash Points are immediately credited to your account (#CASHPOINTS) and reward items are placed into your account Kafra Storage.\n\n🛡️ Alternative & Manual Payment:\nIf you contribute via Bank Wire, GCash, or Crypto, submit your transaction reference ID below for Game Master verification.', 'donations', NULL, '2026-11-23 07:24:54', '2026-11-23 07:24:54');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `description`, `created_at`, `updated_at`) VALUES (19, 'donation_payment_details', 'Accepted Contribution Channels:\n\n1. Instant PayPal Checkout:\nClick the \'Instant PayPal Checkout\' button on any package tier above for immediate automated delivery.\n\n2. G-Cash / E-Wallet:\nAccount Name: FreynixRO Administration\nAccount Number: 0917-555-ROCP (0917-555-7627)\n\n3. Bank Wire / Online Deposit:\nBank Name: Banco de Oro (BDO)\nAccount Name: FreynixRO Operations\nAccount Number: 0048-2819-9401\n\n4. Cryptocurrency (USDT - TRC20):\nWallet: TFreynixROCommunityWalletAddress7788\nNetwork: Tron (TRC20)\n\n*Important: After completing an offline transfer, submit your Transaction Reference ID below for GM verification.', 'donations', NULL, '2026-11-23 07:24:54', '2026-11-23 07:24:54');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `description`, `created_at`, `updated_at`) VALUES (20, 'donation_kafra_guide', 'How to Retrieve Your In-Game Rewards:\n\n1. Cash Points (#CASHPOINTS):\nPoints are automatically attached to your master account. You can verify your balance in-game using the @cashpoints command or by clicking the Cash Shop icon below the mini-map.\n\n2. In-Game Item Rewards (Kafra Storage Vault):\nReward items are delivered directly into your account\'s shared Kafra Storage.\n• Step 1: Log into any character on your account.\n• Step 2: Speak with any Kafra Employee in Prontera (Central: prontera 151, 187), Morroc, Geffen, Payon, or Alberta.\n• Step 3: Select \'Use Storage\' from the menu.\n• Step 4: Your bonus reward items are ready to be withdrawn!', 'donations', NULL, '2026-11-23 07:24:54', '2026-11-23 07:24:54');
INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `description`, `created_at`, `updated_at`) VALUES (21, 'donation_terms', 'Donation Terms & Voluntary Support Policy:\n1. All donations are 100% voluntary contributions made to support FreynixRO server infrastructure and uptime.\n2. In-game Cash Points and bonus storage items are complimentary digital tokens of appreciation.\n3. Donations are non-refundable once processed and delivered.\n4. Game server rules apply equally to all adventurers; donor status provides no exemption from gameplay rules or anti-cheat policies.\n5. For support or payment inquiries, open a ticket on our official Discord community.', 'donations', NULL, '2026-11-23 07:24:54', '2026-11-23 07:24:54');
