INSERT INTO `site_settings` (`id`, `key`, `value`, `group`, `description`, `created_at`, `updated_at`) VALUES (98, 'chronicles_gallery_data', '[{\"id\":1,\"title\":\"Capital City of Prontera\",\"category\":\"Towns\",\"image\":\"https:\\/\\/static.wikia.nocookie.net\\/woaa\\/images\\/0\\/04\\/Prontera.jpg\\/revision\\/latest?cb=20170820230255\",\"caption\":\"The majestic heart of Rune-Midgard bustling with merchants, knights, and adventurers gathering by the fountain.\",\"date\":\"Chronicle I\"},{\"id\":2,\"title\":\"War of Emperium - Castle Siege\",\"category\":\"WoE\",\"image\":\"\\/themes\\/aether-chronicles\\/assets\\/images\\/feat_woe_boss.jpg\",\"caption\":\"Clashing guilds vying for supremacy and imperial glory in the hallowed halls of Kriemhild Castle.\",\"date\":\"Chronicle II\"},{\"id\":3,\"title\":\"Grand Midgard Festival\",\"category\":\"Events\",\"image\":\"\\/themes\\/aether-chronicles\\/assets\\/images\\/news_festival.jpg\",\"caption\":\"Celebrations across Midgard featuring special guild banquet events, mini-games, and rare rewards.\",\"date\":\"Chronicle III\"},{\"id\":4,\"title\":\"Treasure Vaults & Renewal Update\",\"category\":\"Events\",\"image\":\"\\/themes\\/aether-chronicles\\/assets\\/images\\/news_update.jpg\",\"caption\":\"Ancient chests unearthed in the catacombs, laden with refined ores, enchanted gear, and forgotten relics.\",\"date\":\"Chronicle IV\"},{\"id\":5,\"title\":\"Episode XIII: Noghaltz & Odin Shrine\",\"category\":\"Raids\",\"image\":\"\\/themes\\/aether-chronicles\\/assets\\/images\\/header_chronicles_hero_clean.jpg\",\"caption\":\"Expeditions into the fog-shrouded ruins and forgotten temples of the ancient Nordic gods.\",\"date\":\"Chronicle V\"},{\"id\":6,\"title\":\"Rogue Haven & Road to Midgard\",\"category\":\"Towns\",\"image\":\"\\/themes\\/aether-chronicles\\/assets\\/images\\/bottom_strip_clean.jpg\",\"caption\":\"The scenic highways linking Geffen, Morroc, and Payon where caravans traverse under twilight skies.\",\"date\":\"Chronicle VI\"}]', 'general', NULL, '2026-11-24 13:15:22', '2026-11-24 13:15:22');
