INSERT INTO `news` (`id`, `title`, `slug`, `category`, `summary`, `content`, `author_id`, `author_name`, `is_pinned`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES (1, 'Welcome to AetherCP – Next-Gen Ragnarok Control Panel', 'welcome-to-aethercp', 'announcement', 'We are proud to introduce AetherCP, engineered with modern PHP, blazing-fast responsive UI, and full emulator integration.', '## Welcome Adventurers!\n\nAetherCP provides seamless access to your game accounts, real-time leaderboards, character unstuck tools, and item lookups.\n\n### Server Specifications:\n- **Base / Job Rates:** 1000x / 1000x\n- **Item Drop Rates:** 100x\n- **Episode:** 19 – Land of the Snow (Renewal)\n- **Max Level:** 260 / 55\n\nJoin our official community Discord to stay updated with guild sieges and weekly maintenance schedules!', 1, 'Administrator', 1, 1, '2026-11-23 01:52:24', '2026-11-23 01:52:24', '2026-11-23 01:52:24');
INSERT INTO `news` (`id`, `title`, `slug`, `category`, `summary`, `content`, `author_id`, `author_name`, `is_pinned`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES (2, 'Server Maintenance & Renewal Update Notes', 'server-maintenance-update-notes', 'update', 'Review the latest balance changes, War of Emperium castle schedule, and new dungeon instances.', '### Update Highlights:\n1. **Trait Stats & 4th Jobs:** Full balance adjustments.\n2. **War of Emperium:** Castle schedule updated for Wednesday & Saturday nights.\n3. **Item Database:** Updated with latest instance gears and cards.', 1, 'Staff', 0, 1, '2026-11-22 01:52:24', '2026-11-22 01:52:24', '2026-11-22 01:52:24');
INSERT INTO `downloads` (`id`, `title`, `category`, `version`, `file_size`, `url_mirror1`, `url_mirror2`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'Full Game Client (Recommended)', 'Full Client', 'v1.4.0', '2.8 GB', 'https://mega.nz/file/freynix-client', 'https://drive.google.com/freynix-client', 'Complete game client including full BGM, updated renewal sprites, and high-definition client executable.', 1, 1, '2026-11-23 01:52:24', '2026-11-23 01:52:24');
INSERT INTO `downloads` (`id`, `title`, `category`, `version`, `file_size`, `url_mirror1`, `url_mirror2`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'Lite Client Installer', 'Lite Client', 'v1.4.0', '350 MB', 'https://mega.nz/file/freynix-lite', 'https://drive.google.com/freynix-lite', 'Requires existing kRO installation. Extract into your clean Ragnarok directory.', 2, 1, '2026-11-23 01:52:24', '2026-11-23 01:52:24');
INSERT INTO `downloads` (`id`, `title`, `category`, `version`, `file_size`, `url_mirror1`, `url_mirror2`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'Cumulative Manual Patch', 'Manual Patch', 'Patch 2026-11-20', '45 MB', 'https://mega.nz/file/freynix-patch', NULL, 'Extract into game folder if your auto-patcher cannot connect.', 3, 1, '2026-11-23 01:52:24', '2026-11-23 01:52:24');
